#include "PCH.h"

#include "Logging/Log.h"
#include "Plugin/Plugin.h"

namespace
{
	void OnSKSEMessage(SKSE::MessagingInterface::Message* a_msg)
	{
		if (!a_msg) {
			return;
		}
		switch (a_msg->type) {
		case SKSE::MessagingInterface::kDataLoaded:
			avd::plugin::OnDataLoaded();
			break;
		case SKSE::MessagingInterface::kPostLoadGame:
		case SKSE::MessagingInterface::kNewGame:
			avd::plugin::OnGameStart();
			break;
		default:
			break;
		}
	}
}

// Entry point. The plugin declaration/version data is generated by add_commonlibsse_plugin in CMake.
SKSEPluginLoad(const SKSE::LoadInterface* a_skse)
{
	// Second argument false: we install our own logger instead of CommonLib's default.
	SKSE::Init(a_skse, false);
	avd::logging::Init(false);

	logger::info("Advanced View Distance Framework loading (Phase 2 core: settings control, no rendering hooks)");

	const auto* messaging = SKSE::GetMessagingInterface();
	if (!messaging || !messaging->RegisterListener(OnSKSEMessage)) {
		logger::error("Could not register SKSE messaging listener; plugin will remain inactive");
		return true;  // never fail the load over this; stay inert
	}
	return true;
}
